// Spectrum shapes: each peak is a narrow Lorentzian h / (1 + ((x − m)/w)²) at an integer m/z.
const BUTANONE = '6/(1+((x-15)/0.3)^2) + 13/(1+((x-27)/0.3)^2) + 19/(1+((x-29)/0.3)^2) + 5/(1+((x-42)/0.3)^2) + 100/(1+((x-43)/0.3)^2) + 7/(1+((x-57)/0.3)^2) + 25/(1+((x-72)/0.3)^2) + 1.1/(1+((x-73)/0.3)^2)';
